<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{$vps->hostname?:('VPS #'.$vps->id)}} · Nodexa</title><style>:root{--bg:#07111c;--surface:#0b1825;--surface2:#0f2132;--line:#1b3449;--blue:#3b8cff;--text:#edf6ff;--muted:#7e96aa;--green:#42e9a6;--red:#ff6577;--orange:#ffbd59}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,system-ui,-apple-system,"Segoe UI",sans-serif}a{text-decoration:none;color:inherit}.top{height:64px;background:#081522;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 max(18px,calc((100% - 1180px)/2))}.brand{font-size:21px;font-weight:850}.brand b{color:var(--blue)}.back{font-size:12px;color:#a8bdcd}.wrap{max-width:1180px;margin:24px auto;padding:0 18px}.head{display:flex;justify-content:space-between;align-items:flex-start;gap:15px;margin-bottom:20px}.head h1{margin:0 0 5px;font-size:24px}.muted{color:var(--muted);font-size:12px}.status{padding:6px 10px;border-radius:14px;background:rgba(66,233,166,.1);color:var(--green);font-size:11px}.alert{padding:12px 14px;border-radius:6px;margin-bottom:15px;border:1px solid}.ok{background:rgba(66,233,166,.08);border-color:rgba(66,233,166,.25);color:var(--green)}.err{background:rgba(255,101,119,.08);border-color:rgba(255,101,119,.25);color:#ff9baa}.grid{display:grid;grid-template-columns:1.2fr .8fr;gap:16px}.card{background:var(--surface);border:1px solid var(--line);border-radius:8px;overflow:hidden;margin-bottom:16px}.title{padding:13px 15px;background:#0d1d2c;border-bottom:1px solid var(--line);font-size:12px;font-weight:750}.body{padding:15px}.stats{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.stat{background:var(--surface2);border:1px solid var(--line);border-radius:6px;padding:12px}.stat span{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;margin-bottom:5px}.stat strong{font-size: