<div class="title">Strømstyring</div><div class="body powers">@foreach(['boot'=>['Start','green'],'shutdown'=>['Luk ned','orange'],'restart'=>['Genstart',''],'poweroff'=>['Tving sluk','red']] as $action=>$x)<form method="POST" action="/client/vps/{{$vps->id}}/power">@csrf<input type="hidden" name="action" value="{{$action}}"><button class="btn {{$x[1]}}" @if($action==='poweroff') onclick="return confirm('Vil du tvinge VPS’en til at slukke?')" @endif>{{$x[0]}}</button></form>@endforeach</div></section></div><div><section class="card"><div class="title">Nulstil adgangskode</div><form class="body" method="POST" action="/client/vps/{{$vps->id}}/reset-password">@csrf<div class="note">Nulstil adgangskoden til administratorbrugeren på VPS'en.</div><input class="field" name="user" value="root" placeholder="Bruger"><button class="btn">Nulstil adgangskode</button></form></section><section class="card danger"><div class="title">Geninstaller VPS</div><form class="body" method="POST" action="/client/vps/{{$vps->id}}/rebuild" onsubmit="return confirm('ADVARSEL: Alt data på VPS’en slettes. Fortsæt?')">@csrf<div class="note">Geninstallation sletter alt eksisterende data på VPS'en permanent.</div><select class="field" name="os_id" required><option value="">Vælg operativsystem...</option>@foreach($oses as $os) @php($oid=$os['id']??$os['value']??$os['template_id']??'') @php($on=$os['name']??$os['label']??$os['title']??('OS '.$oid))<option value="{{$oid}}" {{$oid==$vps->os_id?'selected':''}}>{{$on}}</option>@endforeach</select><input type="hidden" name="confirm" value="REINSTALL"><button class="btn red">Geninstaller VPS</button></form></section></div></div></main></body></html>